-- Run this in the Supabase SQL Editor to create the application schema.
-- Quoted mixed-case column names preserve the keys expected by the PHP app.

CREATE TABLE IF NOT EXISTS area (
    "AreaID" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "Area_Name" varchar(100) NOT NULL
);

CREATE TABLE IF NOT EXISTS household (
    "HouseholdID" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "CoordinateX" numeric(11, 8) NOT NULL,
    "CoordinateY" numeric(11, 8) NOT NULL,
    "Area_ID" integer NOT NULL REFERENCES area ("AreaID")
);

CREATE TABLE IF NOT EXISTS "user" (
    "UserID" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "First_Name" varchar(50) NOT NULL,
    "Last_Name" varchar(50) NOT NULL,
    "Address" varchar(100) NOT NULL,
    "Email" varchar(50) NOT NULL,
    "Password_Hashed" varchar(255) NOT NULL,
    "User_Type" varchar(25) NOT NULL,
    "Date_Created" date NOT NULL,
    "Date_Updated" date NOT NULL,
    "Date_of_Birth" date NOT NULL,
    "Birth_Certificate" varchar(150),
    "User_Status" varchar(50) NOT NULL,
    "Contact_Number" varchar(20) NOT NULL
);

CREATE TABLE IF NOT EXISTS member (
    "MemberID" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "User_ID" integer NOT NULL REFERENCES "user" ("UserID"),
    "Household_ID" integer NOT NULL REFERENCES household ("HouseholdID")
);

CREATE TABLE IF NOT EXISTS report (
    "ReportID" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "Date_Sent" date NOT NULL,
    "Date_Resolved" date,
    "Report_Message" varchar(200) NOT NULL,
    "Type_of_Problem" varchar(100) NOT NULL,
    "Report_Image" varchar(150) NOT NULL,
    "Household_ID" integer NOT NULL REFERENCES household ("HouseholdID"),
    "report_address" varchar(255),
    "report_status" varchar(20) NOT NULL DEFAULT 'unverified'
        CHECK ("report_status" IN ('unverified', 'ongoing', 'resolved')),
    "located" varchar(255) NOT NULL
);

CREATE TABLE IF NOT EXISTS vulnerability (
    "VulnerabilityID" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "Type_of_Vulnerablity" varchar(50) NOT NULL,
    "Vulnerability_Points" integer NOT NULL,
    "Household_ID" integer REFERENCES household ("HouseholdID"),
    "Area_ID" integer REFERENCES area ("AreaID")
);

CREATE INDEX IF NOT EXISTS household_area_id_idx ON household ("Area_ID");
CREATE INDEX IF NOT EXISTS member_user_id_idx ON member ("User_ID");
CREATE INDEX IF NOT EXISTS member_household_id_idx ON member ("Household_ID");
CREATE INDEX IF NOT EXISTS report_household_id_idx ON report ("Household_ID");
CREATE INDEX IF NOT EXISTS vulnerability_household_id_idx ON vulnerability ("Household_ID");
CREATE INDEX IF NOT EXISTS vulnerability_area_id_idx ON vulnerability ("Area_ID");

INSERT INTO area ("AreaID", "Area_Name") VALUES
    (1, 'Celine Homes'),
    (2, 'East Homes'),
    (3, 'Purok Carvic')
ON CONFLICT ("AreaID") DO NOTHING;

-- BEGIN VERCEL DEPLOYMENT ADDITIONS
-- If the original application schema is already installed, run only this block.
CREATE SCHEMA IF NOT EXISTS app_private;
REVOKE ALL ON SCHEMA app_private FROM PUBLIC, anon, authenticated;

CREATE TABLE IF NOT EXISTS app_private.php_sessions (
    session_id varchar(128) PRIMARY KEY,
    session_data text NOT NULL,
    last_activity bigint NOT NULL
);

CREATE INDEX IF NOT EXISTS php_sessions_last_activity_idx
    ON app_private.php_sessions (last_activity);
REVOKE ALL ON TABLE app_private.php_sessions FROM PUBLIC, anon, authenticated;

INSERT INTO storage.buckets (id, name, public) VALUES
    ('report-uploads', 'report-uploads', false)
ON CONFLICT (id) DO UPDATE SET public = false;
-- END VERCEL DEPLOYMENT ADDITIONS
